{
  "headline": "FDA's records trace our supply to a plant classified OAI 1468 days before the posting",
  "headline_cites": ["D7"],
  "sentences": [
    {
      "text": "FDA first posted the promethazine hydrochloride shortage on 2023-11-21 and it remains Current as of 2026-10-21.",
      "cites": ["E28"]
    },
    {
      "text": "The shortage listing covers Hikma Pharmaceuticals USA, Inc. and XGen Pharmaceuticals DJB, Inc. for injection presentations.",
      "cites": ["E26", "E27"]
    },
    {
      "text": "Our Corvale General stock includes tablets labeled by PD-Rx Pharmaceuticals, Inc. (NDC 43063040505) and Zydus Lifesciences Limited (NDC 65841004110).",
      "cites": ["E2", "E3"]
    },
    {
      "text": "The Zydus Lifesciences Limited label names a registered plant (FEI 3002984011) that received OAI classifications after inspections ending 2014-09-05 and 2019-05-03.",
      "cites": ["E18", "E20", "E25"]
    },
    {
      "text": "FDA's OAI classification letter for the 2019 inspection is dated 2019-11-14, 1468 days before the shortage posting.",
      "cites": ["D7"]
    },
    {
      "text": "The PD-Rx Pharmaceuticals, Inc. plant (FEI 1641825) shows only VAI inspections, most recently ending 2026-08-20.",
      "cites": ["E7", "E8"]
    },
    {
      "text": "The rule‑based transfer option moves 9 tablets of 25 mg from Corvale General (23 days on hand) to Corvale Lakeside (9.6 days on hand), bringing Lakeside to 14 days.",
      "cites": ["D9"]
    }
  ]
}
